create table if not exists public.estatisticas_acessos(id bigint generated by default as identity primary key,visitante_id text not null check(char_length(visitante_id) between 8 and 100),tipo text not null check(tipo in('pagina','clique')),pagina text not null check(char_length(pagina) between 1 and 60),dispositivo text not null check(dispositivo in('celular','computador')),criado_em timestamptz not null default now());
create index if not exists estatisticas_acessos_criado_em_idx on public.estatisticas_acessos(criado_em desc);
alter table public.estatisticas_acessos enable row level security;
drop policy if exists "registrar estatistica anonima" on public.estatisticas_acessos;
create policy "registrar estatistica anonima" on public.estatisticas_acessos for insert to anon,authenticated with check(true);
drop policy if exists "pastor consulta estatisticas" on public.estatisticas_acessos;
create policy "pastor consulta estatisticas" on public.estatisticas_acessos for select to authenticated using(exists(select 1 from public.perfis p where p.id=auth.uid() and p.ativo=true and p.perfil in('pastor','admin')));
revoke update,delete on public.estatisticas_acessos from anon,authenticated;
grant insert on public.estatisticas_acessos to anon,authenticated;
grant select on public.estatisticas_acessos to authenticated;
grant usage,select on sequence public.estatisticas_acessos_id_seq to anon,authenticated;
